static NSData *MYDataFromBase64(NSString *base64) {
    return [[NSData alloc] initWithBase64EncodedString:base64 options:0];
}

static NSImage *MYLogoImage(void) {
    NSData *data = MYDataFromBase64(MYLogoBase64);
    if (!data) return nil;
    return [[NSImage alloc] initWithData:data];
}

static CGFloat MYMainScreenHeight(void) {
    return [[NSScreen screens][0] frame].size.height;
}

static CGRect MYAppKitToCGRect(NSRect r) {
    return CGRectMake(r.origin.x, MYMainScreenHeight() - NSMaxY(r), r.size.width, r.size.height);
}

static void MYShowAlert(NSString *title, NSString *message) {
    NSAlert *alert = [[NSAlert alloc] init];
    alert.messageText = title;
    alert.informativeText = message;
    alert.alertStyle = NSAlertStyleWarning;
    [alert addButtonWithTitle:@"OK"];
    [alert runModal];
}

static unsigned char *MYBitmapPixels(CGImageRef image, size_t *widthOut, size_t *heightOut) {
    size_t w = CGImageGetWidth(image);
    size_t h = CGImageGetHeight(image);
    CGColorSpaceRef cs = CGColorSpaceCreateWithName(kCGColorSpaceSRGB);
    CGContextRef ctx = CGBitmapContextCreate(NULL, w, h, 8, 0, cs, kCGImageAlphaPremultipliedLast | kCGBitmapByteOrder32Big);
    CGColorSpaceRelease(cs);
    if (!ctx) return NULL;
    CGContextDrawImage(ctx, CGRectMake(0, 0, w, h), image);
    unsigned char *src = CGBitmapContextGetData(ctx);
    unsigned char *copy = malloc(w * h * 4);
    if (copy && src) memcpy(copy, src, w * h * 4);
    CGContextRelease(ctx);
    if (widthOut) *widthOut = w;
    if (heightOut) *heightOut = h;
    return copy;
}

static float *MYRowProfile(unsigned char *px, size_t w, size_t h, size_t sy, size_t sx, size_t *rowsOut) {
    size_t rows = h / sy;
    float *prof = calloc(rows, sizeof(float));
    for (size_t r = 0; r < rows; r++) {
        size_t y = r * sy;
        double sum = 0;
        size_t count = 0;
        for (size_t x = 0; x < w; x += sx) {
            unsigned char *p = px + (y * w + x) * 4;
            sum += (p[0] * 299 + p[1] * 588 + p[2] * 114) / 1000.0;
            count++;
        }
        prof[r] = count ? (float)(sum / count) : 0;
    }
    if (rowsOut) *rowsOut = rows;
    return prof;
}

