@interface MYOverlayView : NSView
@property (nonatomic, assign) NSPoint startGlobal;
@property (nonatomic, assign) NSPoint currentGlobal;
@property (nonatomic, assign) BOOL dragging;
@property (nonatomic, copy) void (^onFinish)(NSRect rect, BOOL cancelled);
@end

@implementation MYOverlayView

- (BOOL)isFlipped {
    return NO;
}

- (BOOL)acceptsFirstResponder {
    return YES;
}

- (void)resetCursorRects {
    [self addCursorRect:self.bounds cursor:[NSCursor crosshairCursor]];
}

- (void)drawRect:(NSRect)dirty {
    [[NSColor colorWithCalibratedWhite:0.0 alpha:0.28] setFill];
    NSRectFill(self.bounds);
    if (self.dragging) {
        NSPoint a = [self.window convertPointFromScreen:self.startGlobal];
        NSPoint b = [self.window convertPointFromScreen:self.currentGlobal];
        NSRect sel = NSMakeRect(MIN(a.x, b.x), MIN(a.y, b.y), fabs(a.x - b.x), fabs(a.y - b.y));
        if (sel.size.width > 1 && sel.size.height > 1) {
            [[NSColor clearColor] setFill];
            NSRectFillUsingOperation(sel, NSCompositingOperationClear);
            [[NSColor whiteColor] setStroke];
            NSBezierPath *path = [NSBezierPath bezierPathWithRect:sel];
            path.lineWidth = 2.0;
            [path stroke];
            NSString *sizeText = [NSString stringWithFormat:@"%.0f x %.0f", sel.size.width, sel.size.height];
            NSDictionary *attrs = @{NSFontAttributeName: [NSFont systemFontOfSize:12], NSForegroundColorAttributeName: [NSColor whiteColor]};
            [sizeText drawAtPoint:NSMakePoint(NSMinX(sel), NSMaxY(sel) + 4) withAttributes:attrs];
        }
    }
}

- (void)mouseDown:(NSEvent *)event {
    self.startGlobal = [self.window convertPointToScreen:[event locationInWindow]];
    self.currentGlobal = self.startGlobal;
    self.dragging = YES;
    [self setNeedsDisplay:YES];
}

- (void)mouseDragged:(NSEvent *)event {
    self.currentGlobal = [self.window convertPointToScreen:[event locationInWindow]];
    [self setNeedsDisplay:YES];
}

- (void)mouseUp:(NSEvent *)event {
    self.currentGlobal = [self.window convertPointToScreen:[event locationInWindow]];
    NSPoint a = self.startGlobal;
    NSPoint b = self.currentGlobal;
    NSRect rect = NSMakeRect(MIN(a.x, b.x), MIN(a.y, b.y), fabs(a.x - b.x), fabs(a.y - b.y));
    BOOL cancelled = (rect.size.width < 4 || rect.size.height < 4);
    void (^finish)(NSRect, BOOL) = self.onFinish;
    self.onFinish = nil;
    if (finish) finish(rect, cancelled);
}

- (void)keyDown:(NSEvent *)event {
    if (event.keyCode == 53) {
        void (^finish)(NSRect, BOOL) = self.onFinish;
        self.onFinish = nil;
        if (finish) finish(NSZeroRect, YES);
    } else {
        [super keyDown:event];
    }
}

@end

