- (void)applicationDidFinishLaunching:(NSNotification *)note {
    NSImage *logo = MYLogoImage();
    if (logo) [NSApp setApplicationIconImage:logo];
    [self trackFrontmostApp];
    [self buildMainWindow];
    [self buildStatusItem];
    [self buildMainMenu];
    [self registerHotKey];
    [self.mainWindow makeKeyAndOrderFront:nil];
    [NSApp activateIgnoringOtherApps:YES];
}

- (void)trackFrontmostApp {
    self.lastOtherPID = 0;
    NSRunningApplication *front = [[NSWorkspace sharedWorkspace] frontmostApplication];
    if (front && front.processIdentifier != getpid()) self.lastOtherPID = front.processIdentifier;
    [[NSWorkspace sharedWorkspace].notificationCenter addObserverForName:NSWorkspaceDidActivateApplicationNotification object:nil queue:[NSOperationQueue mainQueue] usingBlock:^(NSNotification *n) {
        NSRunningApplication *app = n.userInfo[NSWorkspaceApplicationKey];
        if (app && app.processIdentifier != getpid()) self.lastOtherPID = app.processIdentifier;
    }];
}

