- (void)refreshModeTexts {
    NSArray *names = @[@"Area Pilihan", @"Seluruh Layar", @"Halaman Browser Penuh"];
    self.hintLabel.stringValue = [NSString stringWithFormat:@"Tekan Control + S untuk memulai tangkapan - mode: %@", names[self.mode]];
    if (self.mode == MYCaptureModePage) {
        self.hintLabel.stringValue = [self.hintLabel.stringValue stringByAppendingString:@" (fokuskan browser dulu, hasil jahitan gulir eksperimental)"];
    }
}

- (void)registerHotKey {
    EventTypeSpec spec;
    spec.eventClass = kEventClassKeyboard;
    spec.eventKind = kEventHotKeyPressed;
    InstallApplicationEventHandler(&MYHotKeyHandler, 1, &spec, (__bridge void *)self, NULL);
    EventHotKeyID hotKeyID;
    hotKeyID.signature = MYHotKeySignature;
    hotKeyID.id = 1;
    OSStatus status = RegisterEventHotKey(kVK_ANSI_S, controlKey, hotKeyID, GetApplicationEventTarget(), 0, &MYHotKeyRef);
    if (status == noErr) {
        self.statusLabel.stringValue = @"Shortcut global: TERDAFTAR (Control + S). Aktif selama proses Mysnap hidup - jendela boleh ditutup, ikon menu bar menjaga aplikasi tetap berjalan.";
    } else {
        MYHotKeyRef = NULL;
        self.statusLabel.stringValue = @"Shortcut global: GAGAL didaftarkan. Control + S kemungkinan bentrok dengan aplikasi lain.";
    }
}

static OSStatus MYHotKeyHandler(EventHandlerCallRef next, EventRef event, void *userData) {
    if (GetEventClass(event) == kEventClassKeyboard && GetEventKind(event) == kEventHotKeyPressed) {
        EventHotKeyID hotKeyID;
        GetEventParameter(event, kEventParamDirectObject, typeEventHotKeyID, NULL, sizeof(hotKeyID), NULL, &hotKeyID);
        if (hotKeyID.signature == MYHotKeySignature) {
            dispatch_async(dispatch_get_main_queue(), ^{
                MYAppDelegate *delegate = (MYAppDelegate *)[NSApp delegate];
                [delegate startCapture];
            });
        }
    }
    return noErr;
}

- (void)applicationWillTerminate:(NSNotification *)note {
    if (MYHotKeyRef) {
        UnregisterEventHotKey(MYHotKeyRef);
        MYHotKeyRef = NULL;
    }
}

- (BOOL)applicationShouldTerminateAfterLastWindowClosed:(NSApplication *)sender {
