- (void)captureClicked:(id)sender {
    [self startCapture];
}

- (void)startCapture {
    if (self.captureInProgress) return;
    self.captureInProgress = YES;
    self.mode = (MYCaptureMode)self.modeControl.selectedSegment;
    [self.previewWindow orderOut:nil];
    self.previewOpen = NO;
    [self.mainWindow orderOut:nil];
    [self.settingsWindow orderOut:nil];
    self.savedLabel.stringValue = @"";
    dispatch_after(dispatch_time(DISPATCH_TIME_NOW, (int64_t)(0.35 * NSEC_PER_SEC)), dispatch_get_main_queue(), ^{
        if (self.mode == MYCaptureModeArea) [self captureArea];
        else if (self.mode == MYCaptureModeFullScreen) [self captureFullScreen];
        else [self capturePage];
    });
}

- (void)captureArea {
    NSMutableArray *overlays = [NSMutableArray array];
    void (^finish)(NSRect, BOOL) = ^(NSRect rect, BOOL cancelled) {
        for (NSWindow *w in overlays) [w orderOut:nil];
        if (cancelled) {
            [self showMainWithMessage:@"Tangkapan area dibatalkan (Esc atau seretan terlalu kecil)."];
            return;
        }
        dispatch_after(dispatch_time(DISPATCH_TIME_NOW, (int64_t)(0.25 * NSEC_PER_SEC)), dispatch_get_main_queue(), ^{
            CGRect cg = MYAppKitToCGRect(rect);
            CGImageRef image = CGWindowListCreateImage(cg, kCGWindowListOptionOnScreenOnly, kCGNullWindowID, kCGWindowImageShouldBeOpaque | kCGWindowImageBestResolution);
            [self deliverCapture:image scale:[NSScreen mainScreen].backingScaleFactor note:@"Mode: Area Pilihan"];
        });
    };
    for (NSScreen *screen in [NSScreen screens]) {
        MYOverlayWindow *window = [[MYOverlayWindow alloc] initWithContentRect:screen.frame styleMask:NSWindowStyleMaskBorderless backing:NSBackingStoreBuffered defer:NO];
        window.level = NSScreenSaverWindowLevel;
        window.opaque = NO;
        window.backgroundColor = [NSColor clearColor];
        window.hasShadow = NO;
        MYOverlayView *view = [[MYOverlayView alloc] initWithFrame:NSMakeRect(0, 0, screen.frame.size.width, screen.frame.size.height)];
        view.onFinish = finish;
        window.contentView = view;
        [overlays addObject:window];
        [window orderFrontRegardless];
        [window makeFirstResponder:view];
    }
    [[overlays firstObject] makeKeyWindow];
}

- (void)captureFullScreen {
    NSPoint mouse = [NSEvent mouseLocation];
    NSScreen *target = [NSScreen mainScreen];
    for (NSScreen *screen in [NSScreen screens]) {
        if (NSPointInRect(mouse, screen.frame)) {
            target = screen;
            break;
        }
    }
    NSNumber *displayNumber = target.deviceDescription[@"NSScreenNumber"];
    CGDirectDisplayID displayID = (CGDirectDisplayID)displayNumber.unsignedIntValue;
    CGImageRef image = CGDisplayCreateImage(displayID);
    [self deliverCapture:image scale:target.backingScaleFactor note:@"Mode: Seluruh Layar"];
}

- (void)deliverCapture:(CGImageRef)image scale:(CGFloat)scale note:(NSString *)note {
    if (!image) {
        NSString *extra = @"";
        NSOperatingSystemVersion version = [NSProcessInfo processInfo].operatingSystemVersion;
        if (version.majorVersion > 10 || (version.majorVersion == 10 && version.minorVersion >= 15)) {
            extra = @" Pada macOS 10.15+ pastikan Mysnap memiliki izin Screen Recording di System Preferences > Security & Privacy > Privacy.";
        }
        MYShowAlert(@"Tangkapan gagal", [NSString stringWithFormat:@"Sistem menolak atau gagal membuat gambar layar.%@", extra]);
        [self showMainWithMessage:@"Tangkapan gagal."];
        return;
    }
    if (self.lastCapture) CGImageRelease(self.lastCapture);
    self.lastCapture = image;
    CGImageRetain(image);
    self.lastScale = scale;
    [self showPreview:note];
}

- (void)showPreview:(NSString *)note {
    size_t w = CGImageGetWidth(self.lastCapture);
    size_t h = CGImageGetHeight(self.lastCapture);
    CGFloat scale = self.lastScale > 0 ? self.lastScale : 1.0;
    NSImage *image = [[NSImage alloc] initWithCGImage:self.lastCapture size:NSMakeSize(w / scale, h / scale)];
    if (!self.previewWindow) [self buildPreviewWindow];
    self.previewImage.image = image;
    NSString *info = [NSString stringWithFormat:@"%zu x %zu px - %@", w, h, note];
    if (self.mode == MYCaptureModePage) {
        info = [info stringByAppendingFormat:@" - jahitan %ld bagian (eksperimental)", (long)self.pageTiles];
        if (self.pageUncertain) info = [info stringByAppendingString:@" - sebagian offset diperkirakan"];
    }
    self.previewInfo.stringValue = info;
    [self fitPreviewImage];
    self.previewOpen = YES;
    self.previewClosing = NO;
    self.captureInProgress = NO;
    [self.previewWindow makeKeyAndOrderFront:nil];
    [NSApp activateIgnoringOtherApps:YES];
}

