- (void)fitPreviewImage {
    NSSize docSize = self.previewScroll.contentView.bounds.size;
    NSSize imageSize = self.previewImage.image.size;
    CGFloat zoom = MIN(docSize.width / MAX(imageSize.width, 1), docSize.height / MAX(imageSize.height, 1));
    if (zoom > 1) zoom = 1;
    NSSize fitted = NSMakeSize(imageSize.width * zoom, imageSize.height * zoom);
    self.previewImage.frame = NSMakeRect(0, 0, fitted.width, fitted.height);
    [self.previewScroll reflectScrolledClipView:self.previewScroll.contentView];
}

- (void)previewCancel:(id)sender {
    self.previewClosing = YES;
    [self.previewWindow orderOut:nil];
    self.previewOpen = NO;
    [self showMainWithMessage:@"Pratinjau ditutup tanpa menyimpan."];
}

- (void)previewRetake:(id)sender {
    self.previewClosing = YES;
    [self.previewWindow orderOut:nil];
    self.previewOpen = NO;
    [self startCapture];
}

- (void)previewSave:(id)sender {
    [self saveCurrentCapture];
}

- (NSString *)ensureSaveFolder {
    NSUserDefaults *defaults = [NSUserDefaults standardUserDefaults];
    NSString *folder = [defaults stringForKey:@"MYSaveFolder"];
    BOOL directory = NO;
    if (folder && [[NSFileManager defaultManager] fileExistsAtPath:folder isDirectory:&directory] && directory && [[NSFileManager defaultManager] isWritableFileAtPath:folder]) {
        return folder;
    }
    NSOpenPanel *panel = [NSOpenPanel openPanel];
    panel.canChooseDirectories = YES;
    panel.canChooseFiles = NO;
    panel.canCreateDirectories = YES;
    panel.message = @"Pilih folder tujuan penyimpanan screenshot Mysnap.";
    if ([panel runModal] == NSModalResponseOK && panel.URL) {
        folder = panel.URL.path;
        [defaults setObject:folder forKey:@"MYSaveFolder"];
        return folder;
    }
    return nil;
}

- (void)saveCurrentCapture {
    if (!self.lastCapture) {
        MYShowAlert(@"Tidak ada gambar", @"Belum ada tangkapan untuk disimpan.");
        return;
    }
    NSString *folder = [self ensureSaveFolder];
    if (!folder) {
        MYShowAlert(@"Penyimpanan dibatalkan", @"Folder tujuan belum dipilih, jadi gambar tidak disimpan. Pratinjau tetap terbuka.");
        return;
    }
    NSUserDefaults *defaults = [NSUserDefaults standardUserDefaults];
    NSString *format = [defaults stringForKey:@"MYFilenameFormat"];
    if (!format || format.length == 0) format = @"Mysnap_yyyy-MM-dd_HH.mm.ss";
    NSDateFormatter *formatter = [[NSDateFormatter alloc] init];
    formatter.locale = [NSLocale localeWithLocaleIdentifier:@"en_US_POSIX"];
    formatter.dateFormat = format;
    NSString *base = [formatter stringFromDate:[NSDate date]];
    base = [base stringByReplacingOccurrencesOfString:@"/" withString:@"-"];
    NSString *path = [folder stringByAppendingPathComponent:[base stringByAppendingString:@".png"]];
    NSFileManager *fm = [NSFileManager defaultManager];
    NSInteger counter = 1;
    while ([fm fileExistsAtPath:path]) {
        path = [folder stringByAppendingPathComponent:[NSString stringWithFormat:@"%@_(%ld).png", base, (long)counter]];
        counter++;
    }
    NSBitmapImageRep *rep = [[NSBitmapImageRep alloc] initWithCGImage:self.lastCapture];
    NSData *png = [rep representationUsingType:NSBitmapImageFileTypePNG properties:@{}];
    if (!png) {
        MYShowAlert(@"Penyimpanan gagal", @"Gambar tidak dapat diubah menjadi data PNG.");
        return;
    }
    NSError *error = nil;
    if (![png writeToFile:path options:NSDataWritingAtomic error:&error]) {
        MYShowAlert(@"Penyimpanan gagal", [NSString stringWithFormat:@"Tidak dapat menulis ke %@. %@", path, error.localizedDescription ?: @""]);
        return;
    }
    self.previewClosing = YES;
    [self.previewWindow orderOut:nil];
    self.previewOpen = NO;
    [self showMainWithMessage:[NSString stringWithFormat:@"Tersimpan: %@", path]];
}

- (void)showMainWithMessage:(NSString *)message {
    self.captureInProgress = NO;
    self.savedLabel.stringValue = message ?: @"";
    [self.mainWindow makeKeyAndOrderFront:nil];
    [NSApp activateIgnoringOtherApps:YES];
}

- (void)openSettings:(id)sender {
    if (!self.settingsWindow) [self buildSettingsWindow];
    [self refreshSettingsFields];
    [self.settingsWindow makeKeyAndOrderFront:nil];
    [NSApp activateIgnoringOtherApps:YES];
}

