    NSTextField *folderTitle = [self staticLabel:@"Folder tujuan penyimpanan (PNG):" frame:NSMakeRect(16, 336, 300, 16)];
    [content addSubview:folderTitle];
    self.folderField = [[NSTextField alloc] initWithFrame:NSMakeRect(16, 308, 380, 24)];
    self.folderField.editable = NO;
    [content addSubview:self.folderField];
    NSButton *chooseFolder = [NSButton buttonWithTitle:@"Pilih Folder..." target:self action:@selector(chooseFolder:)];
    chooseFolder.frame = NSMakeRect(404, 306, 100, 28);
    chooseFolder.bezelStyle = NSBezelStyleRounded;
    [content addSubview:chooseFolder];
    NSTextField *formatTitle = [self staticLabel:@"Format nama file (token NSDateFormatter, mis. yyyy-MM-dd_HH.mm.ss):" frame:NSMakeRect(16, 276, 480, 16)];
    [content addSubview:formatTitle];
    self.formatField = [[NSTextField alloc] initWithFrame:NSMakeRect(16, 248, 380, 24)];
    self.formatField.target = self;
    self.formatField.action = @selector(formatChanged:);
    [content addSubview:self.formatField];
    self.formatExample = [[NSTextField alloc] initWithFrame:NSMakeRect(16, 226, 480, 16)];
    self.formatExample.bezeled = NO;
    self.formatExample.drawsBackground = NO;
    self.formatExample.editable = NO;
    self.formatExample.font = [NSFont systemFontOfSize:11];
    self.formatExample.textColor = [NSColor secondaryLabelColor];
    [content addSubview:self.formatExample];
    NSTextField *loginTitle = [self staticLabel:@"Buka otomatis saat login (Login Items):" frame:NSMakeRect(16, 192, 400, 16)];
    [content addSubview:loginTitle];
    NSTextView *loginText = [[NSTextView alloc] initWithFrame:NSMakeRect(16, 108, 488, 78)];
    loginText.editable = NO;
    loginText.selectable = YES;
    loginText.drawsBackground = NO;
    loginText.font = [NSFont systemFontOfSize:11];
    loginText.string = @"Mysnap tidak mengubah pengaturan login tanpa izin Anda.\nmacOS 10.13-12: System Preferences > Users & Groups > tab Login Items > tombol + > pilih Mysnap.app.\nmacOS 13+: System Settings > General > Login Items > tambahkan Mysnap.app.\nShortcut Control + S hanya berfungsi selama proses Mysnap berjalan.";
    NSScrollView *loginScroll = [[NSScrollView alloc] initWithFrame:NSMakeRect(12, 104, 496, 86)];
    loginScroll.documentView = loginText;
    loginScroll.hasVerticalScroller = YES;
    loginScroll.drawsBackground = NO;
    [content addSubview:loginScroll];
    NSButton *openLogin = [NSButton buttonWithTitle:@"Buka Login Items..." target:self action:@selector(openLoginItems:)];
    openLogin.frame = NSMakeRect(16, 68, 150, 28);
    openLogin.bezelStyle = NSBezelStyleRounded;
    [content addSubview:openLogin];
    self.launchAgentCheck = [[NSButton alloc] initWithFrame:NSMakeRect(16, 40, 400, 20)];
    self.launchAgentCheck.title = @"Mulai otomatis saat login (LaunchAgent, atas izin Anda)";
    self.launchAgentCheck.buttonType = NSButtonTypeSwitch;
    self.launchAgentCheck.target = self;
    self.launchAgentCheck.action = @selector(toggleLaunchAgent:);
    self.launchAgentCheck.font = [NSFont systemFontOfSize:12];
    [content addSubview:self.launchAgentCheck];
    NSButton *close = [NSButton buttonWithTitle:@"Tutup" target:self action:@selector(closeSettings:)];
    close.frame = NSMakeRect(428, 20, 76, 28);
