}

- (NSTextField *)staticLabel:(NSString *)text frame:(NSRect)frame {
    NSTextField *label = [[NSTextField alloc] initWithFrame:frame];
    label.stringValue = text;
    label.bezeled = NO;
    label.drawsBackground = NO;
    label.editable = NO;
    label.font = [NSFont systemFontOfSize:12];
    return label;
}

- (void)refreshSettingsFields {
    NSString *folder = [[NSUserDefaults standardUserDefaults] stringForKey:@"MYSaveFolder"];
    self.folderField.stringValue = folder ?: @"(belum diatur - Anda akan ditanya saat menyimpan pertama kali)";
    NSString *format = [[NSUserDefaults standardUserDefaults] stringForKey:@"MYFilenameFormat"];
    self.formatField.stringValue = format ?: @"Mysnap_yyyy-MM-dd_HH.mm.ss";
    self.launchAgentCheck.state = [[NSFileManager defaultManager] fileExistsAtPath:[self launchAgentPlistPath]] ? NSControlStateValueOn : NSControlStateValueOff;
    [self formatChanged:nil];
}

- (void)formatChanged:(id)sender {
    NSString *format = self.formatField.stringValue;
    if (format.length == 0) format = @"Mysnap_yyyy-MM-dd_HH.mm.ss";
    NSDateFormatter *formatter = [[NSDateFormatter alloc] init];
    formatter.locale = [NSLocale localeWithLocaleIdentifier:@"en_US_POSIX"];
    formatter.dateFormat = format;
    self.formatExample.stringValue = [NSString stringWithFormat:@"Contoh hasil: %@.png", [formatter stringFromDate:[NSDate date]]];
}

- (void)chooseFolder:(id)sender {
    NSOpenPanel *panel = [NSOpenPanel openPanel];
    panel.canChooseDirectories = YES;
    panel.canChooseFiles = NO;
    panel.canCreateDirectories = YES;
    if ([panel runModal] == NSModalResponseOK && panel.URL) {
        [[NSUserDefaults standardUserDefaults] setObject:panel.URL.path forKey:@"MYSaveFolder"];
        [self refreshSettingsFields];
    }
}

- (void)openLoginItems:(id)sender {
    BOOL opened = [[NSWorkspace sharedWorkspace] openFile:@"/System/Library/PreferencePanes/Users.prefPane"];
    if (!opened) {
        MYShowAlert(@"Buka manual", @"Buka System Preferences > Users & Groups > tab Login Items, lalu tambahkan Mysnap.app dengan tombol +.");
    }
}

- (void)closeSettings:(id)sender {
    NSString *format = self.formatField.stringValue;
    NSUserDefaults *defaults = [NSUserDefaults standardUserDefaults];
    if (format.length > 0) [defaults setObject:format forKey:@"MYFilenameFormat"];
    [defaults synchronize];
    [self.settingsWindow orderOut:nil];
}

- (void)buildStatusItem {
    self.statusItem = [[NSStatusBar systemStatusBar] statusItemWithLength:NSSquareStatusItemLength];
    NSImage *icon = MYLogoImage();
    if (icon) {
        icon.size = NSMakeSize(18, 18);
        self.statusItem.button.image = icon;
    }
    NSMenu *menu = [[NSMenu alloc] init];
    NSMenuItem *show = [[NSMenuItem alloc] initWithTitle:@"Tampilkan Mysnap" action:@selector(statusShow:) keyEquivalent:@""];
    show.target = self;
    [menu addItem:show];
    NSMenuItem *capture = [[NSMenuItem alloc] initWithTitle:@"Tangkap Sekarang" action:@selector(statusCapture:) keyEquivalent:@""];
    capture.target = self;
    [menu addItem:capture];
    NSMenuItem *settings = [[NSMenuItem alloc] initWithTitle:@"Pengaturan..." action:@selector(statusSettings:) keyEquivalent:@""];
    settings.target = self;
    [menu addItem:settings];
    [menu addItem:[NSMenuItem separatorItem]];
    NSMenuItem *quit = [[NSMenuItem alloc] initWithTitle:@"Keluar Mysnap" action:@selector(statusQuit:) keyEquivalent:@""];
    quit.target = self;
    [menu addItem:quit];
    self.statusItem.menu = menu;
}

- (void)buildMainMenu {
    NSMenu *mainMenu = [[NSMenu alloc] init];
    NSMenuItem *appMenuItem = [[NSMenuItem alloc] init];
    NSMenu *appMenu = [[NSMenu alloc] initWithTitle:@"Mysnap"];
    [appMenu addItemWithTitle:@"Sembunyikan Mysnap" action:@selector(hide:) keyEquivalent:@"h"];
    [appMenu addItem:[NSMenuItem separatorItem]];
    [appMenu addItemWithTitle:@"Keluar Mysnap" action:@selector(terminate:) keyEquivalent:@"q"];
    [appMenuItem setSubmenu:appMenu];
    [mainMenu addItem:appMenuItem];
    [NSApp setMainMenu:mainMenu];
}

- (void)statusShow:(id)sender {
    [self showMainWithMessage:@""];
}

- (void)statusCapture:(id)sender {
    [self startCapture];
}

- (void)statusSettings:(id)sender {
    [self openSettings:nil];
}

- (void)statusQuit:(id)sender {
    [NSApp terminate:nil];
}

- (NSString *)launchAgentPlistPath {
    NSString *dir = [NSHomeDirectory() stringByAppendingPathComponent:@"Library/LaunchAgents"];
    return [dir stringByAppendingPathComponent:@"com.mysnap.agent.plist"];
}

- (void)runLaunchctl:(NSArray *)arguments {
    NSTask *task = [[NSTask alloc] init];
    task.launchPath = @"/bin/launchctl";
    task.arguments = arguments;
    @try {
        [task launch];
        [task waitUntilExit];
    } @catch (NSException *e) {
    }
}

- (void)toggleLaunchAgent:(id)sender {
    NSString *path = [self launchAgentPlistPath];
    NSFileManager *fm = [NSFileManager defaultManager];
    if (self.launchAgentCheck.state == NSControlStateValueOn) {
        NSString *dir = [path stringByDeletingLastPathComponent];
        NSError *dirError = nil;
        if (![fm fileExistsAtPath:dir] && ![fm createDirectoryAtPath:dir withIntermediateDirectories:YES attributes:nil error:&dirError]) {
            self.launchAgentCheck.state = NSControlStateValueOff;
            MYShowAlert(@"Gagal memasang LaunchAgent", [NSString stringWithFormat:@"Tidak dapat membuat folder %@. %@", dir, dirError.localizedDescription ?: @""]);
            return;
        }
        NSDictionary *plist = @{
            @"Label": @"com.mysnap.agent",
            @"ProgramArguments": @[[[NSBundle mainBundle] executablePath]],
            @"RunAtLoad": @YES,
            @"LimitLoadToSessionType": @"Aqua"
        };
        if (![plist writeToFile:path atomically:YES]) {
            self.launchAgentCheck.state = NSControlStateValueOff;
            MYShowAlert(@"Gagal memasang LaunchAgent", [NSString stringWithFormat:@"Tidak dapat menulis %@.", path]);
            return;
        }
        [self runLaunchctl:@[@"load", @"-w", path]];
        MYShowAlert(@"LaunchAgent dipasang", @"Mysnap akan otomatis berjalan di latar setiap Anda login, sehingga Control + S siap dipakai tanpa membuka aplikasi terlebih dahulu. Matikan kapan saja lewat kotak centang yang sama.");
    } else {
        [self runLaunchctl:@[@"unload", @"-w", path]];
        [fm removeItemAtPath:path error:nil];
    }
}

- (void)showHud:(NSString *)text {
    if (!self.hudWindow) {
        NSRect frame = NSMakeRect(0, 0, 320, 44);
        self.hudWindow = [[NSWindow alloc] initWithContentRect:frame styleMask:NSWindowStyleMaskBorderless backing:NSBackingStoreBuffered defer:NO];
        self.hudWindow.level = NSFloatingWindowLevel;
        self.hudWindow.opaque = NO;
        self.hudWindow.backgroundColor = [NSColor colorWithCalibratedWhite:0.1 alpha:0.85];
        self.hudWindow.ignoresMouseEvents = YES;
        self.hudLabel = [[NSTextField alloc] initWithFrame:NSMakeRect(12, 12, 296, 20)];
        self.hudLabel.bezeled = NO;
        self.hudLabel.drawsBackground = NO;
        self.hudLabel.editable = NO;
        self.hudLabel.alignment = NSTextAlignmentCenter;
        self.hudLabel.font = [NSFont systemFontOfSize:12];
        self.hudLabel.textColor = [NSColor whiteColor];
        [self.hudWindow.contentView addSubview:self.hudLabel];
    }
    self.hudLabel.stringValue = text;
    [self.hudWindow center];
    [self.hudWindow orderFrontRegardless];
}

- (void)hideHud {
    [self.hudWindow orderOut:nil];
}

- (void)capturePage {
    if (!AXIsProcessTrusted()) {
        NSAlert *alert = [[NSAlert alloc] init];
        alert.messageText = @"Mode Halaman Browser butuh izin Accessibility";
        alert.informativeText = @"Mysnap harus mengirim kejadian gulir (scroll) ke browser untuk menjahit halaman penuh. Izinkan Mysnap di System Preferences > Security & Privacy > Privacy > Accessibility, lalu coba lagi. Tanpa izin ini mode gulir tidak dapat bekerja.";
        [alert addButtonWithTitle:@"Buka Preferensi"];
        [alert addButtonWithTitle:@"Batal"];
        NSInteger response = [alert runModal];
        if (response == NSAlertFirstButtonReturn) {
            [[NSWorkspace sharedWorkspace] openFile:@"/System/Library/PreferencePanes/Security.prefPane"];
        }
        [self showMainWithMessage:@"Mode halaman browser dibatalkan: izin Accessibility belum diberikan."];
        return;
    }
    pid_t targetPID = self.lastOtherPID;
    if (targetPID == 0) {
        [self showMainWithMessage:@"Tidak tahu jendela mana yang ditangkap: fokuskan browser terlebih dahulu."];
        return;
    }
    CGWindowID windowID = 0;
    CGRect bounds = CGRectNull;
    CFArrayRef list = CGWindowListCopyWindowInfo(kCGWindowListOptionOnScreenOnly, kCGNullWindowID);
    for (NSDictionary *entry in (__bridge NSArray *)list) {
        NSNumber *pid = entry[(__bridge NSString *)kCGWindowOwnerPID];
        NSNumber *layer = entry[(__bridge NSString *)kCGWindowLayer];
        if (pid.intValue == targetPID && layer.intValue == 0) {
            windowID = (CGWindowID)[entry[(__bridge NSString *)kCGWindowNumber] unsignedIntValue];
            CGRectMakeWithDictionaryRepresentation((__bridge CFDictionaryRef)entry[(__bridge NSString *)kCGWindowBounds], &bounds);
            break;
        }
    }
    CFRelease(list);
    if (windowID == 0 || CGRectIsNull(bounds)) {
        [self showMainWithMessage:@"Jendela browser tidak ditemukan di layar."];
        return;
    }
    [self showHud:@"Menjahit halaman... bagian 1"];
    [self stitchTile:0 windowID:windowID bounds:bounds tiles:[NSMutableArray array] offsets:[NSMutableArray array] previousProfile:NULL];
}

- (void)stitchTile:(NSInteger)index windowID:(CGWindowID)windowID bounds:(CGRect)bounds tiles:(NSMutableArray *)tiles offsets:(NSMutableArray *)offsets previousProfile:(float *)previousProfile {
    CGImageRef tile = CGWindowListCreateImage(bounds, kCGWindowListOptionIncludingWindow, windowID, kCGWindowImageShouldBeOpaque);
    if (!tile) {
        if (previousProfile) free(previousProfile);
        [self hideHud];
        MYShowAlert(@"Tangkapan gagal", @"Sistem menolak menangkap jendela browser. Pada macOS 10.15+ beri izin Screen Recording untuk Mysnap.");
        [self showMainWithMessage:@"Mode halaman browser gagal menangkap jendela."];
        return;
    }
    size_t w = 0, h = 0;
    unsigned char *pixels = MYBitmapPixels(tile, &w, &h);
    size_t rows = 0;
    float *profile = MYRowProfile(pixels, w, h, 4, 8, &rows);
    free(pixels);
    size_t sy = 4;
    NSInteger offset = 0;
    BOOL uncertain = NO;
    BOOL reachedBottom = NO;
    if (index > 0 && previousProfile) {
        size_t maxSample = rows / 2;
        size_t bestSo = 0;
        float bestCost = 1e9;
        for (size_t so = 0; so <= maxSample; so++) {
            size_t n = rows - so;
            if (n == 0) break;
            double sum = 0;
            for (size_t i = 0; i < n; i++) sum += fabs(profile[i] - previousProfile[so + i]);
            float cost = (float)(sum / n);
            if (cost < bestCost) {
                bestCost = cost;
                bestSo = so;
            }
        }
        if (bestSo == 0 && bestCost < 1.5) {
            reachedBottom = YES;
        } else if (bestCost < 10.0 && bestSo > 0) {
            offset = (NSInteger)(bestSo * sy);
        } else {
            offset = (NSInteger)(h / 2);
            uncertain = YES;
        }
        free(previousProfile);
        previousProfile = NULL;
    }
    if (index > 0) {
        if (reachedBottom) {
            CGImageRelease(tile);
            free(profile);
            [self finishStitch:tiles offsets:offsets uncertain:uncertain];
            return;
        }
        [offsets addObject:@(offset)];
    }
    [tiles addObject:(__bridge id)tile];
    CGImageRelease(tile);
    if (index >= 39) {
        free(profile);
        [self finishStitch:tiles offsets:offsets uncertain:uncertain];
        return;
    }
    NSInteger step = (NSInteger)(bounds.size.height / 2);
    CGPoint center = CGPointMake(CGRectGetMidX(bounds), CGRectGetMidY(bounds));
    CGEventRef scroll = CGEventCreateScrollWheelEvent(NULL, kCGScrollEventUnitPixel, 1, -step);
    if (scroll) {
        CGEventSetLocation(scroll, center);
        CGEventPost(kCGHIDEventTap, scroll);
        CFRelease(scroll);
    }
    [self showHud:[NSString stringWithFormat:@"Menjahit halaman... bagian %ld", (long)(index + 2)]];
    float *nextPrevious = profile;
    dispatch_after(dispatch_time(DISPATCH_TIME_NOW, (int64_t)(0.55 * NSEC_PER_SEC)), dispatch_get_main_queue(), ^{
        [self stitchTile:index + 1 windowID:windowID bounds:bounds tiles:tiles offsets:offsets previousProfile:nextPrevious];
    });
}

- (void)finishStitch:(NSMutableArray *)tiles offsets:(NSMutableArray *)offsets uncertain:(BOOL)uncertain {
    [self hideHud];
    if (tiles.count == 0) {
        [self showMainWithMessage:@"Mode halaman browser tidak menghasilkan gambar."];
        return;
    }
    CGImageRef first = (__bridge CGImageRef)tiles[0];
    size_t w = CGImageGetWidth(first);
    size_t h = CGImageGetHeight(first);
    size_t total = h;
    for (NSNumber *number in offsets) total += (size_t)number.integerValue;
    CGColorSpaceRef cs = CGColorSpaceCreateWithName(kCGColorSpaceSRGB);
    CGContextRef ctx = CGBitmapContextCreate(NULL, w, total, 8, 0, cs, kCGImageAlphaPremultipliedLast | kCGBitmapByteOrder32Big);
    CGColorSpaceRelease(cs);
    if (!ctx) {
        MYShowAlert(@"Gagal menjahit", @"Tidak dapat membuat kanvas gabungan.");
        [self showMainWithMessage:@"Mode halaman browser gagal menjahit."];
        return;
    }
    size_t cursor = 0;
    CGContextDrawImage(ctx, CGRectMake(0, total - cursor - h, w, h), first);
    for (size_t i = 1; i < tiles.count; i++) {
        CGImageRef tile = (__bridge CGImageRef)tiles[i];
        size_t tileH = CGImageGetHeight(tile);
        cursor += (size_t)[offsets[i - 1] integerValue];
        CGContextDrawImage(ctx, CGRectMake(0, total - cursor - tileH, w, tileH), tile);
    }
    CGImageRef result = CGBitmapContextCreateImage(ctx);
    CGContextRelease(ctx);
    self.pageTiles = (NSInteger)tiles.count;
    self.pageUncertain = uncertain;
    [self deliverCapture:result scale:[NSScreen mainScreen].backingScaleFactor note:@"Mode: Halaman Browser Penuh"];
    if (result) CGImageRelease(result);
}

@end

int main(int argc, const char *argv[]) {
    @autoreleasepool {
        NSApplication *app = [NSApplication sharedApplication];
        [app setActivationPolicy:NSApplicationActivationPolicyRegular];
        MYAppDelegate *delegate = [[MYAppDelegate alloc] init];
        app.delegate = delegate;
        [app run];
    }
    return 0;
}
